ALTER POLICY tax_original_read ON storage.objects USING (bucket_id='tax-impact-originals' AND EXISTS (SELECT 1 FROM public.tax_impact_analyses a WHERE a.client_tenant_id::text=(storage.foldername(storage.objects.name))[1] AND a.id::text=(storage.foldername(storage.objects.name))[2] AND public.tax_impact_access(a.client_tenant_id)));
ALTER POLICY tax_original_insert ON storage.objects WITH CHECK (bucket_id='tax-impact-originals' AND lower(storage.extension(storage.objects.name))='xlsx' AND EXISTS (SELECT 1 FROM public.tax_impact_analyses a WHERE a.client_tenant_id::text=(storage.foldername(storage.objects.name))[1] AND a.id::text=(storage.foldername(storage.objects.name))[2] AND public.tax_impact_access(a.client_tenant_id)));
ALTER POLICY tax_original_delete_unregistered ON storage.objects USING (bucket_id='tax-impact-originals' AND EXISTS (SELECT 1 FROM public.tax_impact_analyses a WHERE a.client_tenant_id::text=(storage.foldername(storage.objects.name))[1] AND a.id::text=(storage.foldername(storage.objects.name))[2] AND public.tax_impact_access(a.client_tenant_id)) AND NOT EXISTS (SELECT 1 FROM public.tax_impact_imports i WHERE i.storage_path=storage.objects.name));